    public static class R24Dt11Definition
    {
        public const string Id="dt11",Family="shells";public const int Capacity=2,Pellets=8;public const float Interval=.2f,Scale=1.6f,Range=40,PelletDamage=12,ChamberFit=.4269203092f;
        public static readonly Float3 Muzzle=new Float3(0,.04f,.65f),Hinge=new Float3(0,-.135f,.13f),Foregrip=new Float3(0,-.025f,.36f);
        static Float3 Moving(Float3 p,float angle){float c=(float)Math.Cos(angle),s=(float)Math.Sin(angle);return new Float3(p.X,Hinge.Y+p.Y*c-p.Z*s,Hinge.Z+p.Y*s+p.Z*c);}
        public static Float3 Chamber(float angle){return Moving(new Float3(0,.175f,-.017f),angle);}public static Float3 Offer(float angle){var a=Chamber(angle);return new Float3(a.X,a.Y+.11f-.0127f/Scale,a.Z);}public static Float3 CloseGrip(float angle){var a=Moving(new Float3(0,.09f,.27f),angle);return new Float3(a.X,a.Y,a.Z-.06f);}
        public static float DamageAtDistance(float distance){return float.IsNaN(distance)||float.IsInfinity(distance)||distance<0||distance>Range?0:PelletDamage*(1-.75f*Math.Max(0,Math.Min(1,(distance-8)/17)));}
        public static bool Reach(Float3 point,Float3 centre,float radius){float x=(point.X-centre.X)*Scale,y=(point.Y-centre.Y)*Scale,z=(point.Z-centre.Z)*Scale;if(!point.IsFinite||!centre.IsFinite||x*x+y*y+z*z>.34f*.34f)return false;x=Math.Max(0,Math.Abs(x)-.035f);if(z>0)z=Math.Max(0,z-.04f);return x*x+y*y+z*z<Math.Pow(Math.Min(radius+.055f,.30f),2);}
    }
    public sealed class R24Dt11Volley
    {
        public readonly string InstanceId;public readonly CommandContext Command;public readonly long Shot;public readonly bool Supported;public readonly Float3 Origin;public readonly HandlingSnapshot Before,After;readonly Float3[] directions;public Float3[] Directions{get{return(Float3[])directions.Clone();}}public float Range{get{return R24Dt11Definition.Range;}}
        internal R24Dt11Volley(string id,CommandContext c,R23M1014Pose pose,HandlingSnapshot before,HandlingSnapshot after,float spread,bool supported){Supported=supported;InstanceId=id;Command=c;Shot=after.Shots;Origin=pose.Origin;Before=before;After=after;directions=DirectionsFor(pose,spread);}
        public static Float3[] DirectionsFor(R23M1014Pose pose,float spread=1){if(!pose.Valid||float.IsNaN(spread)||float.IsInfinity(spread)||spread<.6799f||spread>1)throw new ArgumentException("source DT11 unit muzzle/spread");var a=new Float3[8];for(int i=0;i<8;i++){double theta=i*Math.PI*2/8,r=Math.Tan(4*spread*Math.PI/180)*(i%2==0?.45:1),x=Math.Cos(theta)*r,y=Math.Sin(theta)*r,u=pose.Forward.X+pose.Right.X*x+pose.Up.X*y,v=pose.Forward.Y+pose.Right.Y*x+pose.Up.Y*y,w=pose.Forward.Z+pose.Right.Z*x+pose.Up.Z*y,n=Math.Sqrt(u*u+v*v+w*w);a[i]=new Float3((float)(u/n),(float)(v/n),(float)(w/n));}return a;}
    }
    public sealed class R24Dt11Owner
    {
        sealed class Initial:IWeaponLifetimeAuthority{readonly CommandContext creation;readonly string id;internal Initial(CommandContext c,string instance){creation=c;id=instance;}public RuleResult AuthorizeNew(CommandContext c,string instance,WeaponMechanism mechanism,int rounds){return c.SessionId==creation.SessionId&&c.ActorId==creation.ActorId&&c.CommandId==creation.CommandId&&c.Tick==creation.Tick&&c.AuthorityEpoch==creation.AuthorityEpoch&&c.IsAuthority&&instance==id&&rounds==2?RuleResult.Accept():RuleResult.Reject("source DT11 initial2 entitlement");}public RuleResult AuthorizeRestore(CommandContext c,string instance,string actor,long epoch){return RuleResult.Reject("retained local DT11 owner");}}
        readonly WeaponHandling weapon;readonly IRevisionedAmmoReserve reserve;readonly float spread;bool retired;
        public string InstanceId{get;private set;}public int Reserve{get{return reserve.Available;}}public bool ReloadGripInProgress{get{return weapon.Dt11SwipeHeld;}}public int LiveMask{get{return weapon.Dt11LiveMask;}}public int SpentMask{get{return weapon.Dt11SpentMask;}}public float EjectionAngle{get{return weapon.Dt11EjectionAngle;}}public long OpenEvents{get{return weapon.Dt11OpenEvents;}}
        public HandlingSnapshot Snapshot{get{var s=weapon.Snapshot;s.ClaimsSupport|=s.Phase!=ReloadPhase.Ready;return s;}}public bool GripToggle{get{return weapon.GripToggle;}set{if(weapon.GripToggle!=value){weapon.GripToggle=value;SuspendControls();}}}
        public string ReloadCue{get;private set;}public bool HapticSupport{get;private set;}public float HapticAmplitude{get;private set;}public float HapticSeconds{get;private set;}
        public R24Dt11Owner(CommandContext creation,string instanceId,IRevisionedAmmoReserve shells,IAuthorityGate authority,float spreadScale=1){if(shells==null||authority==null||string.IsNullOrEmpty(instanceId)||float.IsNaN(spreadScale)||float.IsInfinity(spreadScale)||spreadScale<.6799f||spreadScale>1)throw new ArgumentException("source DT11 identity/reserve/spread");var lifetime=new WeaponLifetimes(creation.SessionId,new Initial(creation,instanceId));WeaponHandling active;var accepted=lifetime.CreateDt11(creation,instanceId,shells,authority,out active);if(!accepted.Accepted)throw new InvalidOperationException(accepted.Reason);weapon=active;reserve=shells;spread=spreadScale;InstanceId=instanceId;}
        public void SuspendControls(){weapon.SuspendDt11();ReloadCue=null;HapticAmplitude=HapticSeconds=0;}public void Retire(){SuspendControls();retired=true;}
        public RuleResult Apply(CommandContext c,HandlingAction action,HandlingInput input,R23M1014Pose pose,out R24Dt11Volley volley,bool triggerBlocksFlick=false){volley=null;ReloadCue=null;HapticAmplitude=HapticSeconds=0;HapticSupport=false;if(retired)return RuleResult.Reject("retired DT11");if(input.Enabled&&!input.Paused&&input.PrimaryTracked&&!input.PrimaryClimbing&&!input.HeadObstructed&&input.Trigger&&(action==HandlingAction.Sample||action==HandlingAction.Fire)&&!pose.Valid)return RuleResult.Reject("actual DT11 firing pose");var before=Snapshot;var result=weapon.ApplyDt11(c,action,input,triggerBlocksFlick);var after=Snapshot;if(after.Shots==before.Shots+1){volley=new R24Dt11Volley(InstanceId,c,pose,before,after,spread,weapon.Dt11ShotSupported);HapticAmplitude=.8f;HapticSeconds=.085f;}if(after.Phase!=before.Phase){ReloadCue=after.Phase==ReloadPhase.NeedsMagazine?"mag_eject":after.Phase==ReloadPhase.NeedsRack?"mag_insert":after.Phase==ReloadPhase.Ready?"bolt":null;HapticSupport=true;HapticAmplitude=.45f;HapticSeconds=.06f;}return result;}
    }
